// Generated by AgentFoundry Agent Foundry — kit: claude-agent-sdk-ts
// Docs: https://docs.claude.com/en/api/agent-sdk/overview
//
// The HPC Career counsellor: a chat with one student, using only the five
// tools in ./tools (built with AgentFoundry's Tool Builder, wired to the
// app's tested code). No file, shell or web access.
//
// Run (from counsellor/): npm install && npm run agent:dev
//   - one question: npx tsx agent.ts "Which careers suit me?" (what the
//     agent card's Send in AgentFoundry runs)
//   - chat: no argument, then one message per line on stdin
// Requires a Claude login or ANTHROPIC_API_KEY in .env / .env.local.
//
// Every run is recorded to .codenow/runs/hpc-counsellor/ (JSONL) so you can replay
// it in the AgentFoundry IDE's Runs tab. The recorder fails silently — it will
// never break your agent.
//
// If a AgentFoundry Sidecar is running on this host (see ./sidecar.ts), its
// skills + guardrails are composed into the system prompt automatically.
// Without a sidecar the prefix is empty and the agent runs unchanged.

import * as fs from "node:fs";
import * as readline from "node:readline";

// Load .env / .env.local into process.env so ANTHROPIC_API_KEY reaches the
// SDK without needing the dotenv package or `node --env-file=…`. AgentFoundry's
// runsFork spawns this script with an inherited process.env that doesn't
// see your interactive shell's exports, so the script must self-load.
for (const envFile of [".env", ".env.local"]) {
  try {
    for (const line of fs.readFileSync(envFile, "utf-8").split("\n")) {
      const m = line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*?)\s*$/);
      if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^"(.*)"$/, "$1");
    }
  } catch (_) { /* file optional */ }
}

import { query, type SDKUserMessage } from "@anthropic-ai/claude-agent-sdk";
import { record } from "./recorder";
import { loadSidecarSystemPrompt } from "./sidecar";
import { get_my_resultServer } from "./tools/get_my_result";
import { search_careersServer } from "./tools/search_careers";
import { get_careerServer } from "./tools/get_career";
import { save_planServer } from "./tools/save_plan";
import { alert_teacherServer } from "./tools/alert_teacher";

const SLUG = "hpc-counsellor";
const MODEL = process.env.COUNSELLOR_MODEL ?? "claude-opus-5-5";

const MCP_SERVERS = {
  "get-my-result": get_my_resultServer,
  "search-careers": search_careersServer,
  "get-career": get_careerServer,
  "save-plan": save_planServer,
  "alert-teacher": alert_teacherServer,
};
const ALLOWED_TOOLS = Object.keys(MCP_SERVERS).map((server) => `mcp__${server}__${server.replace(/-/g, "_")}`);

// The system prompt is versioned in AgentFoundry's Prompts tab.
function loadSystemPrompt(): string {
  const file = new URL("./.codenow/agent-studio/prompts/hpc-counsellor-system.md", import.meta.url);
  return fs.readFileSync(file, "utf-8").replace(/^---[\s\S]*?---\s*/, "").trim();
}

// One student's conversation: a single question from the command line, or
// one turn per line on stdin.
async function* turns(question?: string): AsyncGenerator<SDKUserMessage> {
  const lines = question ? [question] : readline.createInterface({ input: process.stdin });
  for await (const line of lines) {
    const text = line.trim();
    if (text) yield { type: "user", message: { role: "user", content: text }, parent_tool_use_id: null };
  }
}

async function main() {
  const question = process.argv[2];
  const sidecarPrompt = await loadSidecarSystemPrompt();
  const systemPrompt = sidecarPrompt
    ? `${sidecarPrompt}\n\n---\n\n${loadSystemPrompt()}`
    : loadSystemPrompt();
  const stream = query({
    prompt: turns(question),
    options: {
      model: MODEL,
      systemPrompt,
      tools: [], // no built-in file, shell or web tools
      mcpServers: MCP_SERVERS,
      allowedTools: ALLOWED_TOOLS,
      settingSources: [], // ignore CLAUDE.md and local settings
    },
  });
  for await (const message of record(stream, { slug: SLUG, input: question ?? "(chat)", kit: "claude-agent-sdk-ts", model: MODEL })) {
    if (message.type === "assistant") {
      for (const block of message.message.content) {
        if (block.type === "tool_use") console.log(`Tool: ${block.name.replace(/^mcp__[^_]+(?:-[^_]+)*__/, "")} ${JSON.stringify(block.input)}`);
      }
    } else if (message.type === "result") {
      console.log(message.subtype === "success" ? message.result : `agent error: ${message.subtype}`);
    }
  }
}

main().catch((err) => {
  console.error("agent error:", err);
  process.exit(1);
});
